4	 *
5	 * D-002: for gen-0, "an instance" = a sandboxed fleet bee. `runInstance` administers ONE corpus
6	 * case to ONE bee (D-003): it spawns a `role:bee` agent via the hardened fleet path
7	 * (`spawnAgentInHarness`), hands it the case prompt as its brief, then awaits a terminal state with
8	 * a bounded timeout. The bee runs opus-4-8 @ xhigh (the runner pins `AGENT_MODELS`; bees have no
9	 * committed `ROLE_MODEL_DEFAULTS` floor — see role-models.ts).
10	 *
11	 * Terminal-state mapping (what the battery does with the outcome):
12	 *   - `done` / `failed`     → the instance RAN; return the handle so collectAndDistill + the judge
13	 *                              read the real outcome. A bee that attempted-but-failed the case is a
14	 *                              valid scored data point, NOT a runInstance error.
15	 *   - `cancelled` / `reaped` → an INVALID run (manual cancel / host died mid-flight) → throw, so the
16	 *                              orchestrator records it `errored` (re-runnable), never a fake "failed
17	 *                              the task".
18	 *   - never reached terminal within the timeout → throw (a harness hang, not a task outcome).
19	 *
20	 * The spawn + poll host-effects are INJECTED (`BeeRunDeps`) so the await/timeout/mapping logic
21	 * unit-tests with fakes — zero spawn, zero spend. `liveBeeRunDeps` / `makeLiveBeeTraceLoaders` bind
22	 * the real ones (fleet spawn + org-PG + on-disk transcript) for the runner (P-004).
23	 */
24	import type postgres from 'postgres';
25	import { readFileSync } from 'node:fs';
26	import { classifySubprocessResult } from '@papercusp/papercup-shared/agent';
27	import { spawnAgentInHarness } from '../fleet/operator-spawn';
28	import type { BeekeeperRunInput } from './beekeeper-runner';
29	import type { InstanceRunHandle } from './instance-manifest';
30	import {
31	  locateBeeTranscript,
32	  type BeeSpawnRow,
33	  type BeeRunTokens,
34	  type BeeTraceLoaders,
35	} from './bee-trace';
36	
37	/** Terminal spawned_agents states. */
38	const TERMINAL = new Set(['done', 'failed', 'cancelled', 'reaped']);
39	
40	export interface SpawnOnceResult {
41	  ok: boolean;
42	  spawnId: string | null;
43	  error: string | null;
44	}
45	
46	/** The host effects `runInstance` needs, injected for testability. */
47	export interface BeeRunDeps {
48	  /** Launch one bee with the case prompt as its brief; resolve once the child is launched. */
49	  spawn(input: { brief: string; runInput: BeekeeperRunInput }): Promise<SpawnOnceResult>;
50	  /** The bee's current spawned_agents status, or null if the row isn't visible yet. */
51	  pollStatus(spawnId: string): Promise<string | null>;
52	  /** Total solver $cost for the run so far (agent_usage_samples), for the handle + spend cap. */
53	  loadCost(spawnId: string): Promise<number>;
54	  /** output_tail + error_message of a `failed` bee — to classify a transient rate-limit/overload
55	   *  (→ relaunch) vs a genuine task failure (→ score). */
56	  loadFailureText(spawnId: string): Promise<string>;
57	  sleep(ms: number): Promise<void>;
58	  now(): number;
59	  /** Fired before a rate-limited/overloaded bee is relaunched (observability). */
60	  onRateLimitRetry?(info: { spawnId: string; attempt: number; backoffMs: number; cls: string }): void;
61	}
62	
63	export interface BeeRunConfig {
64	  /** Bounded wall-clock per case — on overrun the run is `errored`, never hangs the battery. */
65	  timeoutMs: number;
66	  /** Poll cadence while awaiting a terminal state. */
67	  pollMs: number;
68	  /** Max RELAUNCHES when a bee fails on a transient rate-limit/overload (the owner's hit-limit →
69	   *  relaunch loop; the fleet AIMD governor lowers concurrency in parallel). 0 = no retry. */
70	  maxRateRetries: number;
71	  /** Floor backoff before a rate-limit relaunch; the server's retry-after wins when larger. */
72	  rateBackoffMs: number;
73	}
74	
75	/**
76	 * Build the real `runInstance`: spawn one bee for the case, await a terminal state, map it, and
77	 * return an `InstanceRunHandle` keyed to the bee's spawn id (which IS the instanceId collectAndDistill
78	 * reads). Throws on spawn rejection, timeout, or an invalid (cancelled/reaped) terminal.
79	 */
80	export function makeBeeRunInstance(cfg: BeeRunConfig, deps: BeeRunDeps) {
81	  const handleFor = async (spawnId: string, variant: string): Promise<InstanceRunHandle> => ({
82	    instanceId: spawnId,
83	    instanceUrl: `bee://${spawnId}`,
84	    targetSlug: variant,
85	    costUsd: await deps.loadCost(spawnId).catch(() => 0),
86	  });
87	
88	  return async (input: BeekeeperRunInput): Promise<InstanceRunHandle> => {
89	    // Relaunch loop: a bee that FAILS on a transient rate-limit / overload is re-spawned (a FRESH
90	    // bee) up to maxRateRetries, after a backoff (the server's retry-after, floored). The fleet
91	    // AIMD governor halves the effective concurrency in parallel, so each relaunch lands at a
92	    // lower cap — the owner's hit-limit → lower-cap → relaunch → converge loop.
93	    for (let attempt = 0; ; attempt++) {
94	      const res = await deps.spawn({ brief: input.case.prompt, runInput: input });
95	      if (!res.ok || !res.spawnId) {
96	        throw new Error(`runInstance: spawn rejected for case ${input.case.id}: ${res.error ?? 'unknown'}`);
97	      }
98	      const spawnId = res.spawnId;
99	
100	      const deadline = deps.now() + cfg.timeoutMs;
101	      let status: string | null = null;
102	      while (deps.now() < deadline) {
103	        await deps.sleep(cfg.pollMs);
104	        status = await deps.pollStatus(spawnId);
105	        if (status && TERMINAL.has(status)) break;
106	      }
107	
108	      if (!status || !TERMINAL.has(status)) {
109	        throw new Error(
110	          `runInstance: bee ${spawnId} did not reach a terminal state within ${cfg.timeoutMs}ms (last=${status ?? 'unseen'})`,
111	        );
112	      }
113	      if (status === 'done') return handleFor(spawnId, input.case.variant);
114	      if (status === 'cancelled' || status === 'reaped') {
115	        throw new Error(`runInstance: bee ${spawnId} ended '${status}' — invalid run, re-runnable`);
116	      }
117	
118	      // status === 'failed' — classify the cause from the bee's output (the canonical classifier
119	      // scans stdout on failure, incl. claude's stdout-only "· Rate limited" line).
120	      const failText = await deps.loadFailureText(spawnId).catch(() => '');
121	      const te = classifySubprocessResult({ exitCode: 1, stdout: failText });
122	      const transient = te.class === 'rate_limited' || te.class === 'overloaded';
123	
124	      if (transient && attempt < cfg.maxRateRetries) {
125	        const backoffMs = Math.max(cfg.rateBackoffMs, te.retryAfterMs ?? 0);
126	        deps.onRateLimitRetry?.({ spawnId, attempt, backoffMs, cls: te.class });
127	        await deps.sleep(backoffMs);
128	        continue; // relaunch a FRESH bee for the same case
129	      }
130	      if (transient || te.class === 'usage_limit') {
131	        // Exhausted retries (or a hard usage cap) → surface as rate-limited so the orchestrator
132	        // records `rate_limited` (NOT a scored task-failure). The 'rate-limited' in the message
133	        // triggers the orchestrator's isRateLimitError.
134	        throw new Error(
135	          `runInstance: bee ${spawnId} rate-limited (${te.class}) after ${attempt} relaunch${attempt === 1 ? '' : 'es'} — giving up`,
136	        );
137	      }
138	      // Genuine task failure (agent_crash, etc.) → a real, scoreable outcome.
139	      return handleFor(spawnId, input.case.variant);
140	    }
141	  };
142	}
143	
144	// ───────────────────────────── live bindings (for the runner, P-004) ─────────────────────────────
145	
146	/** Read the columns bee-trace needs from a spawned_agents row. */
147	async function readSpawnRow(sql: postgres.Sql, spawnId: string): Promise<BeeSpawnRow | null> {
148	  const rows = await sql<
149	    {
150	      status: string;
151	      run_id: string | null;
152	      started_at: Date | null;
153	      finished_at: Date | null;
154	      duration_ms: string | null;
155	      output_tail: string | null;
156	      error_message: string | null;
157	    }[]
158	  >`
159	    SELECT status, run_id, started_at, finished_at, duration_ms, output_tail, error_message
160	      FROM harness_shared.spawned_agents
161	     WHERE spawn_id = ${spawnId}
162	     LIMIT 1`;
163	  const r = rows[0];
164	  if (!r) return null;
165	  return {
166	    status: r.status,
167	    runId: r.run_id,
168	    // The org pool returns timestamptz as STRINGS (not Date) — the collectors call .getTime(),
169	    // so coerce. (The testcontainer connection returns Dates, which is why tests didn't catch it.)
170	    startedAt: r.started_at ? new Date(r.started_at) : null,
171	    finishedAt: r.finished_at ? new Date(r.finished_at) : null,
172	    durationMs: r.duration_ms != null ? Number(r.duration_ms) : null,
173	    outputTail: r.output_tail,
174	    errorMessage: r.error_message,
175	  };
176	}
177	
178	/** Sum a run's token totals from agent_usage_samples (null when none landed → transcript fallback). */
179	async function readRunTokens(sql: postgres.Sql, runId: string): Promise<BeeRunTokens | null> {
180	  const rows = await sql<{ input_tokens: string | null; output_tokens: string | null }[]>`
181	    SELECT SUM(COALESCE(input_tokens, 0))::text AS input_tokens,
182	           SUM(COALESCE(output_tokens, 0))::text AS output_tokens
183	      FROM harness_shared.agent_usage_samples
184	     WHERE run_id = ${runId}`;
185	  const r = rows[0];
186	  if (!r || (r.input_tokens == null && r.output_tokens == null)) return null;
187	  const inputTokens = Number(r.input_tokens ?? 0);
188	  const outputTokens = Number(r.output_tokens ?? 0);
189	  if (!inputTokens && !outputTokens) return null;
190	  return { inputTokens, outputTokens };
191	}
192	
193	/** Sum a run's $cost from agent_usage_samples (0 when none priced). */
194	async function readRunCostByRunId(sql: postgres.Sql, runId: string): Promise<number> {
195	  const rows = await sql<{ cost_usd: string | null }[]>`
196	    SELECT SUM(COALESCE(cost_usd, 0))::text AS cost_usd
197	      FROM harness_shared.agent_usage_samples
198	     WHERE run_id = ${runId}`;
199	  return Number(rows[0]?.cost_usd ?? 0) || 0;
200	}
201	
202	/** Live `BeeTraceLoaders`: org-PG spawn/token reads + the on-disk transcript. */
203	export function makeLiveBeeTraceLoaders(sql: postgres.Sql, transcriptBaseDir?: string): BeeTraceLoaders {
204	  return {
205	    loadSpawn: (spawnId) => readSpawnRow(sql, spawnId),
206	    loadRunTokens: (runId) => readRunTokens(sql, runId),
207	    loadTranscript: (spawnId) => {
208	      const path = locateBeeTranscript(spawnId, transcriptBaseDir);
209	      if (!path) return null;
210	      try {
211	        return readFileSync(path, 'utf8');
212	      } catch {
213	        return null;
214	      }
215	    },
216	  };
217	}
218	
219	/** Resolve a spawn's run_id then sum its solver cost — the handle's `costUsd` (for the spend cap). */
220	async function loadCostBySpawn(sql: postgres.Sql, spawnId: string): Promise<number> {
221	  const rows = await sql<{ run_id: string | null }[]>`
222	    SELECT run_id FROM harness_shared.spawned_agents WHERE spawn_id = ${spawnId} LIMIT 1`;
223	  const runId = rows[0]?.run_id;
224	  return runId ? readRunCostByRunId(sql, runId) : 0;
225	}
226	
227	/**
228	 * Live `BeeRunDeps`: the fleet spawn path + org-PG status/cost polls. `harness` + `workspaceId` scope
229	 * the spawn; the case prompt is delivered as the bee's `brief`. (A richer delivery — a work_item per
230	 * case — is a P-008 refinement if a brief-only spawn proves taskless; the brief carries a complete,
231	 * self-contained corpus prompt, which is a real task.)
232	 */
233	export function liveBeeRunDeps(args: {
234	  sql: postgres.Sql;
235	  workspaceId: string;
236	  harness: string;
237	  parentSpawnId?: string | null;
238	  planSlug?: string | null;
239	}): BeeRunDeps {
240	  return {
241	    async spawn({ brief, runInput }) {
242	      const res = await spawnAgentInHarness({
243	        workspaceId: args.workspaceId,
244	        harness: args.harness,
245	        role: 'bee',
246	        brief,
247	        parentSpawnId: args.parentSpawnId ?? null,
248	        parentRole: 'apiary-runner',
249	        planSlug: args.planSlug ?? null,
250	        extras: [`APIARY_CASE=${runInput.case.id}`, `APIARY_REPEAT=${runInput.repeat}`],
251	      });
252	      return { ok: res.ok, spawnId: res.spawnId, error: res.error };
253	    },
254	    async pollStatus(spawnId) {
255	      const rows = await args.sql<{ status: string }[]>`
256	        SELECT status FROM harness_shared.spawned_agents WHERE spawn_id = ${spawnId} LIMIT 1`;
257	      return rows[0]?.status ?? null;
258	    },
259	    async loadFailureText(spawnId) {
260	      const rows = await args.sql<{ output_tail: string | null; error_message: string | null }[]>`
261	        SELECT output_tail, error_message FROM harness_shared.spawned_agents WHERE spawn_id = ${spawnId} LIMIT 1`;
262	      const r = rows[0];
263	      return `${r?.error_message ?? ''}\n${r?.output_tail ?? ''}`;
264	    },
265	    loadCost: (spawnId) => loadCostBySpawn(args.sql, spawnId),
266	    sleep: (ms) => new Promise<void>((r) => setTimeout(r, ms)),
267	    now: () => Date.now(),
268	  };
269	}
