52	/**
53	 * The deterministic SAFETY-FLOOR ceiling on concurrently-running spawns — the
54	 * single fleet-wide number, NOT a per-path allocator (P-007). Folds the old
55	 * hardcoded operator-spawn cap (`MAX_CONCURRENT_SPAWNS=10`) and the orchestrator
56	 * dispatch cap into ONE configurable value: `operator:rate_limit_config`'s
57	 * `maxSimultaneousAgents` (default 16, live-editable, clamped ≤ RATE_LIMIT_MAX_CEILING).
58	 * The governor's global gate + the orchestrator dispatch ceiling + the await pump
59	 * already read this same number, so every spawn path now draws from one ledger.
60	 * This is the absolute hard backstop; the WORTH-IT allocation is the brain's call
61	 * (P-005), informed by `getSpawnHeadroom`.
62	 */
63	export function spawnConcurrencyCeiling(): number {
64	  return getCachedRateLimitConfig().maxSimultaneousAgents;
65	}
