67	/**
68	 * The wake key an over-ceiling spawn attempt sleeps on (D-004 — queue + await,
69	 * never silent-drop): `events:await { event: spawnSlotEventKey(ws) }`, end the
70	 * turn, retry the spawn on wake. Emitted whenever a slot frees — a spawn
71	 * completes (done/failed/cancelled) or the P-011 reclaim frees orphaned rows.
72	 * The wake is a BROADCAST to all waiters (they re-check the ceiling on retry;
73	 * the await pump's per-tick resume cap + per-subscriber coalescing keep a
74	 * mass-wake paced) — slot fairness is re-check-on-wake, not a granted ticket
75	 * like lock:grant.
76	 */
77	export function spawnSlotEventKey(workspaceId: string): string {
78	  return `spawn-slot:freed:${workspaceId}`;
79	}
