81	/**
82	 * Memoized lazy import of the await engine — keeps this module's load graph
83	 * light (the engine pulls the coord/messages surface) and gives concurrent
84	 * announces ONE shared import promise (concurrent dynamic imports of the same
85	 * module can reject under the vitest module runner).
86	 */
87	let awaitEngine: Promise<typeof import('../events/await/engine')> | null = null;
88	const loadAwaitEngine = () => (awaitEngine ??= import('../events/await/engine'));
89	
90	/**
91	 * Announce freed spawn capacity to over-ceiling waiters (best-effort, never
92	 * throws).
93	 */
94	async function announceSpawnSlotFreed(workspaceId: string, summary: string): Promise<void> {
95	  try {
96	    const { emitAwaitedEvent } = await loadAwaitEngine();
97	    await emitAwaitedEvent({
98	      key: spawnSlotEventKey(workspaceId),
99	      summary,
100	      source: 'operator-spawn',
101	      workspaceId,
102	    });
103	  } catch {
104	    /* best-effort — a missed announce just means waiters retry on their
105	       await timeout instead of the early wake */
106	  }
107	}
