109	/**
110	 * Reclaim orphaned rows AND wake over-ceiling waiters in every workspace the
111	 * reclaim freed slots in (D-004). The reclaim itself stays the pure sql unit
112	 * (spawn-reclaim.ts); the announce rides this call-site wrapper.
113	 */
114	async function reclaimAndAnnounce(): Promise<void> {
115	  const r = await reclaimOrphanedSpawns(getOrgPg().sql).catch(
116	    () => ({ reclaimed: 0, spawnIds: [], workspaces: [] }),
117	  );
118	  // Rare (only when orphans were actually freed) — await so the announce lands
119	  // before the caller's cap check; announceSpawnSlotFreed never throws.
120	  await Promise.all(
121	    r.workspaces.map((ws) => announceSpawnSlotFreed(ws, `${r.reclaimed} orphaned spawn slot(s) reclaimed`)),
122	  );
123	}
