125	/**
126	 * The live limit/headroom the brain consults before deciding whether a spawn is
127	 * worth it (P-007): the unified ceiling, how many slots are in use right now, and
128	 * the remaining headroom. Reclaims orphaned rows first so the count reflects live
129	 * spawns only. This is the read the brain-as-allocator (P-005) is fed.
130	 */
131	export async function getSpawnHeadroom(workspaceId: string): Promise<{
132	  ceiling: number;
133	  running: number;
134	  headroom: number;
135	}> {
136	  await reclaimAndAnnounce();
137	  const ceiling = spawnConcurrencyCeiling();
138	  const running = await countRunning(workspaceId).catch(() => 0);
139	  return { ceiling, running, headroom: Math.max(0, ceiling - running) };
140	}
