142	/**
143	 * In-process abort handles for spawns THIS host launched, keyed by spawnId
144	 * (EI-40). `fleet:cancel` flips the durable rows + releases locks/claims; this
145	 * is the other half — actually SIGTERM/SIGKILL the running child so a cancelled
146	 * spawn stops making edits instead of running to INVOKE_TIMEOUT. Only this
147	 * host's live spawns are here; spawns on another operator process aren't — those
148	 * are reclaimed by the P-011 heartbeat-staleness sweep (`reclaimOrphanedSpawns`):
149	 * a host that dies stops heartbeating, and its 'running' rows are freed once
150	 * stale so they stop poisoning the concurrency ceiling.
151	 */
152	const localSpawnAborts = new Map<string, AbortController>();
153	
154	/**
155	 * Per-spawn stream activity (liveness-hardening P-008): epoch-ms of the
156	 * latest stdout/stderr chunk each LOCAL spawn emitted (set by the runner's
157	 * onOutputActivity callback — in-process, no tee files) and the value last
158	 * persisted, so the heartbeat tick only stamps rows whose output actually
159	 * advanced. Entries die with the spawn (cleared beside localSpawnAborts).
160	 */
161	const localSpawnOutput = new Map<string, { at: number; persistedAt: number }>();
162	
163	function noteSpawnOutput(spawnId: string): void {
164	  const e = localSpawnOutput.get(spawnId);
165	  if (e) e.at = Date.now();
166	  else localSpawnOutput.set(spawnId, { at: Date.now(), persistedAt: 0 });
167	}
