169	/**
170	 * Wedge auto-reap threshold (P-010 / D-006, owner decision 2026-06-11): a bee
171	 * stream-silent this long is hung, not thinking — bees stream with
172	 * --include-partial-messages, so thinking deltas + tool_use events keep the
173	 * stream moving; the only legitimate long silence is awaiting a long local
174	 * tool call, which 30 minutes absorbs. Override: PAPERCUSP_WEDGE_REAP_MS.
175	 */
176	export const WEDGE_REAP_SILENT_MS = (() => {
177	  const raw = Number(process.env.PAPERCUSP_WEDGE_REAP_MS);
178	  return Number.isFinite(raw) && raw >= 60_000 ? raw : 30 * 60_000;
179	})();
180	
181	/** Spawns currently being reaped — guards double-fire across ticks while the
182	 *  cancel + process death settle. */
183	const wedgeReapInFlight = new Set<string>();
184	
185	/**
186	 * Pure candidate filter for the wedge reaper (exported for tests): tracked
187	 * local spawns with OBSERVED output whose stream has been silent past the
188	 * threshold, minus those already mid-reap. Never-output spawns are excluded —
189	 * absence of signal is not evidence of a wedge (mirrors isPossiblyWedged).
190	 */
191	export function selectWedgeReapCandidates(
192	  output: ReadonlyMap<string, { at: number }>,
193	  tracked: ReadonlySet<string>,
194	  inFlight: ReadonlySet<string>,
195	  now: number,
196	  silentMs: number = WEDGE_REAP_SILENT_MS,
197	): string[] {
198	  const out: string[] = [];
199	  for (const [id, e] of output) {
200	    if (tracked.has(id) && !inFlight.has(id) && e.at > 0 && now - e.at > silentMs) out.push(id);
201	  }
202	  return out;
203	}
204	
205	/**
206	 * Reap local spawns that are wedged past the threshold (flag-gated, D-006):
207	 * the durable cancel (claims + locks released, coord notice — the SAME engine
208	 * as fleet:cancel) then the local process abort. Only spawns THIS host
209	 * supervises are candidates — the host that holds the handle owns the verdict.
210	 * Spawns with NO observed output are never reaped (absence ≠ wedge).
211	 */
212	async function reapWedgedLocalSpawns(now: number): Promise<void> {
213	  const candidates = selectWedgeReapCandidates(
214	    localSpawnOutput,
215	    new Set(localSpawnAborts.keys()),
216	    wedgeReapInFlight,
217	    now,
218	  );
219	  if (candidates.length === 0) return;
220	  if (!(await getFlag(FLAGS.WEDGE_AUTO_REAP, 'system'))) return;
221	  const { cancelSubtree } = await import('./nursery');
222	  const { sql } = getOrgPg();
223	  for (const spawnId of candidates) {
224	    wedgeReapInFlight.add(spawnId);
225	    try {
226	      const rows = await sql<{ workspace_id: string }[]>`
227	        SELECT workspace_id FROM harness_shared.spawned_agents
228	         WHERE spawn_id = ${spawnId} AND status IN ('running', 'restarting') LIMIT 1`;
229	      const workspaceId = rows[0]?.workspace_id;
230	      if (!workspaceId) continue; // already terminal — nothing to reap
231	      const silentMin = Math.round((now - (localSpawnOutput.get(spawnId)?.at ?? now)) / 60_000);
232	      console.warn(`[wedge-reap] ${spawnId}: stream silent ${silentMin}min with a live process — cancelling (D-006)`);
233	      await cancelSubtree(sql, {
234	        workspaceId,
235	        rootSpawnId: spawnId,
236	        reason: `wedge-reap: alive but stream-silent ${silentMin}min (> ${Math.round(WEDGE_REAP_SILENT_MS / 60_000)}min, D-006)`,
237	        actor: {
238	          ownerId: 'wedge-reaper',
239	          ownerLabel: 'system · wedge-reaper',
240	          source: 'signed-spawn',
241	          workspaceId,
242	          userId: null,
243	        },
244	      });
245	      abortLocalSpawn(spawnId);
246	    } catch (err) {
247	      console.warn(`[wedge-reap] ${spawnId} failed (will retry next tick):`, err);
248	      wedgeReapInFlight.delete(spawnId);
249	    }
250	  }
251	}
