293	/**
294	 * Abort a locally-tracked running spawn (SIGTERM → SIGKILL). Returns true when a
295	 * live local handle was found and signalled. Called by the fleet:cancel tool for
296	 * each cancelled spawn id after the durable subtree flip.
297	 */
298	export function abortLocalSpawn(spawnId: string): boolean {
299	  const ctrl = localSpawnAborts.get(spawnId);
300	  if (!ctrl) return false;
301	  try { ctrl.abort(); } catch { /* already aborted */ }
302	  return true;
303	}
