368	async function countRunning(workspaceId: string, db?: Db): Promise<number> {
369	  const sql = db ?? getOrgPg().sql;
370	  const rows = await sql<{ n: string }[]>`
371	    SELECT count(*)::text AS n FROM harness_shared.spawned_agents
372	     WHERE workspace_id = ${workspaceId} AND status IN ('running', 'restarting')`;
373	  return Number(rows[0]?.n ?? 0);
