458	      harnessSlug: input.harness ?? null,
459	      parentSpawnId: input.parentSpawnId ?? null,
460	      parentRole: input.parentRole ?? 'operator',
461	      childRole: input.role || '(missing)',
462	      runId: `opspawn-${Date.now()}`,
