483	/**
484	 * EI-249: a brief must reach the bee FULLY SUBSTITUTED. The 2026-06-10
485	 * dispatch-pack launched agents whose brief still held the literal `brief-NN`
486	 * template placeholder (no number filled in), so six surplus bees had to
487	 * race-claim lanes off coord presence — a claim-race stampede. The queen-wave
488	 * compiler now substitutes `{item}` up front (`buildWaveFeatures`), but
489	 * `spawnAgentInHarness` is the ONE chokepoint every launch path funnels through
490	 * (chat `<spawn>`, `fleet:spawn`, `place_batch`), so a fail-loud backstop here
491	 * refuses ANY un-substituted brief regardless of caller — option (a) of the
492	 * issue ("refuse to launch when the prompt still matches the placeholder").
493	 *
494	 * Detects the repo's `{item}` template token (the one `buildWaveFeatures`
495	 * substitutes) and the historical `brief-NN` dispatch-pack placeholder. Tight
496	 * by design — a real brief never contains either — so false positives are nil.
497	 * Returns the offending placeholder text (for the error message), or null.
498	 */
499	const BRIEF_PLACEHOLDER_RE = /\{item\}|\bbrief-NN\b/i;
500	export function findBriefPlaceholder(brief: string | null | undefined): string | null {
501	  if (!brief) return null;
502	  const m = BRIEF_PLACEHOLDER_RE.exec(brief);
503	  return m ? m[0] : null;
504	}
