506	/**
507	 * Spawn one agent of `role` into the named harness's project dir, tracked in the
508	 * durable nursery. Returns immediately after the child process is launched
509	 * (fire-and-forget); the background completion flips the row to done/failed.
510	 */
511	export async function spawnAgentInHarness(
512	  input: OperatorSpawnInput,
513	): Promise<OperatorSpawnResult> {
514	  const role = (input.role ?? '').trim();
515	  const fail = async (error: string): Promise<OperatorSpawnResult> => {
516	    console.error(`[operator-spawn] ${error}`);
517	    const spawnId = await recordFailedAttempt(input, error);
518	    return { ok: false, spawnId, harness: input.harness ?? null, projectDir: null, error };
519	  };
520	
