925	  // if the gateway service is down the bee's request is refused rather than bursting direct.
926	  // P-004 (multi-credential routing): when INFERENCE_GATEWAY_MULTI_ACCOUNT is ALSO on, pin this bee
927	  // to a pool account (sticky → harness-pin → 5h-budget drain) via ANTHROPIC_CUSTOM_HEADERS, so its
928	  // per-credential conversation cache survives and the aggregate Max budget across subscriptions
929	  // stays filled (D-003). Fail-soft: any error → no header → the gateway routes to its active()
930	  // account (today's single-credential behavior).
931	  const gwOn = await getFlag(FLAGS.INFERENCE_GATEWAY, 'system');
932	  let routeAccountId: string | undefined;
933	  if (gwOn && (await getFlag(FLAGS.INFERENCE_GATEWAY_MULTI_ACCOUNT, 'system'))) {
934	    routeAccountId = await selectSpawnAccount(input.workspaceId, slug).catch(() => undefined);
935	  }
936	  Object.assign(extraEnv, gatewaySpawnEnv(gwOn, { accountId: routeAccountId }));
937	  // account-aware-rate-governor-routing Phase 1: run the bee UNDER the selected account so the
938	  // spawn-side governor (orchestrator-runner) keys its rate bucket PER-ACCOUNT
939	  // (`anthropic:opus@<id>`) instead of the account-blind global `anthropic:opus`. Without this a
940	  // single account's 429 pauses the class bucket and freezes EVERY opus spawn even while other
941	  // accounts sit idle (owner's "rate-limit-with-headroom = routing bug"). selectSpawnAccount only
942	  // ever returns an AVAILABLE account, so the keyed per-account bucket admits.
943	  if (routeAccountId) extraEnv.PAPERCUSP_ACCOUNT_ID = routeAccountId;
944	
945	  // Register an abort handle so fleet:cancel can stop the child (EI-40).
946	  const abort = new AbortController();
947	  localSpawnAborts.set(spawnId, abort);
948	  ensureSpawnHeartbeatLoop();
949	
950	  // Fire-and-forget: the spawn returns now; completion lands on the nursery row.
951	  let finalStatus: 'done' | 'failed' | 'cancelled' | null = null;
952	  void spawnInvokeOnce(project.path, role, extras, extraEnv, {
953	    signal: abort.signal,
954	    forceSessionId,
955	    ...(input.timeoutMs ? { timeoutMs: input.timeoutMs } : {}),
956	    // EI-85: record the child OS pid + this host so the reclaim sweep can
957	    // /proc-liveness-check the process instead of mislabeling a stale-heartbeat
958	    // row (host briefly paused) as a dead child. Best-effort — a missed write
959	    // just degrades to the heartbeat-stale reclaim.
960	    onChildPid: (pid) => {
961	      void recordSpawnPid(getOrgPg().sql, spawnId, pid).catch(() => {});
962	    },
963	    // P-008: per-chunk stream signal, persisted by the heartbeat tick.
964	    onOutputActivity: () => noteSpawnOutput(spawnId),
965	  })
966	    .then(async (r) => {
967	      finalStatus = abort.signal.aborted ? 'cancelled' : (r.exitCode === 0 ? 'done' : 'failed');
968	      // WI-222: post-bee-exit work-item completion safety net. A bee placed on a
969	      // feature that claimed it (→ in_progress), implemented + committed, and exited
970	      // rc=0 WITHOUT landing work_items:complete leaves the feature non-terminal — the
971	      // placement-watchdog then re-places the dead-holder/non-terminal unit until the
972	      // cursed breaker trips. The DBOS pipeline closes this loop on its terminal DONE
973	      // (reconcileDoneStatus), but that path never runs for hive members, so settle it
974	      // here with the SAME conservative guard (in_progress/validating → passed only;
975	      // never force-pass todo/failing/deprecated). The predicate no-ops every non-bee /
976	      // crashed / cancelled / featureless exit; the call is best-effort (never throws).
977	      await maybeReconcileBeeCompletion(
978	        {
979	          role,
980	          exitCode: r.exitCode,
981	          aborted: abort.signal.aborted,
982	          featureId: input.featureId,
983	          harnessSlug: slug,
984	          workspaceId: input.workspaceId,
985	        },
986	        { log: (m) => console.log(`[operator-spawn] ${spawnId} ${m}`) },
987	      );
988	      return finishSpawn(sql, {
989	        spawnId,
990	        workspaceId: input.workspaceId,
991	        status: finalStatus,
992	        exitCode: r.exitCode,
993	        errorMessage: (r.stderr || '').slice(-2000) || null,
994	        outputTail: (r.output || '').slice(-2000) || null,
995	      });
996	    })
997	    .catch((err) => {
998	      finalStatus = abort.signal.aborted ? 'cancelled' : 'failed';
999	      return finishSpawn(sql, {
1000	        spawnId,
1001	        workspaceId: input.workspaceId,
1002	        status: finalStatus,
1003	        errorMessage: err instanceof Error ? err.message : String(err),
1004	      }).catch(() => { /* PG down — nothing left to record to */ });
1005	    })
1006	    .finally(() => {
1007	      localSpawnAborts.delete(spawnId);
1008	      localSpawnOutput.delete(spawnId);
1009	      // The terminal flip above freed a ceiling slot — wake any over-ceiling
1010	      // waiter sleeping on the slot key (D-004). Best-effort, off the hot path.
1011	      void announceSpawnSlotFreed(input.workspaceId, `spawn ${spawnId} finished — ceiling slot freed`);
1012	      // EI-108: Wake parent on child death (if the spawn has a parent)
1013	      if (finalStatus) {
1014	        void wakeParentOnChildDeath(sql, spawnId, input.workspaceId, finalStatus).catch(() => {
1015	          /* best-effort — logged inside wakeParentOnChildDeath */
1016	        });
1017	      }
1018	    });
1019	
1020	  return { ok: true, spawnId, harness: slug, projectDir: project.path, error: null };
1021	}
